CREATE WAREHOUSE IF NOT EXISTS analytics_wh
  WAREHOUSE_SIZE = 'XSMALL'
  AUTO_SUSPEND = 60            -- seconds idle before suspending
  AUTO_RESUME = TRUE
  INITIALLY_SUSPENDED = TRUE;

USE WAREHOUSE analytics_wh;

-- Temporarily scale up for a heavy backfill, then back down
ALTER WAREHOUSE analytics_wh SET WAREHOUSE_SIZE = 'LARGE';
-- ... run the backfill ...
ALTER WAREHOUSE analytics_wh SET WAREHOUSE_SIZE = 'XSMALL';

SHOW WAREHOUSES LIKE 'analytics_wh';
-- name: ANALYTICS_WH  state: SUSPENDED  size: X-Small  auto_suspend: 60 ...

CREATE DATABASE IF NOT EXISTS shop;
CREATE SCHEMA IF NOT EXISTS shop.raw;
USE SCHEMA shop.raw;

CREATE TABLE orders (id INT, amount NUMBER(10, 2));
SELECT * FROM shop.raw.ORDERS;      -- same table: unquoted names are upper-cased

CREATE TABLE "orders" (id INT);     -- a DIFFERENT, case-sensitive table
SHOW TABLES IN SCHEMA shop.raw;
-- ORDERS
-- orders

SELECT GET_DDL('TABLE', 'ORDERS');
-- create or replace TABLE ORDERS ( ID NUMBER(38,0), AMOUNT NUMBER(10,2) );

CREATE OR REPLACE TABLE customers (
  id         INT PRIMARY KEY,          -- declared, NOT enforced
  email      VARCHAR NOT NULL,         -- NOT NULL is enforced
  balance    NUMBER(12, 2),
  created_at TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  profile    VARIANT
);

INSERT INTO customers (id, email, balance) VALUES (1, 'a@x.io', 10), (1, 'b@x.io', 5);
SELECT COUNT(*) FROM customers;          -- 2  (duplicate id accepted!)

-- Cheaper table for reloadable staging data
CREATE TRANSIENT TABLE stg_customers AS SELECT * FROM customers;

-- Session-only scratch table
CREATE TEMPORARY TABLE tmp_ids AS SELECT DISTINCT id FROM customers;

CREATE FILE FORMAT csv_fmt TYPE = CSV SKIP_HEADER = 1
  FIELD_OPTIONALLY_ENCLOSED_BY = '"' NULL_IF = ('', 'NULL');

CREATE STAGE raw_stage FILE_FORMAT = csv_fmt;

-- From SnowSQL / Snowflake CLI: upload (and gzip) a local file
PUT file:///tmp/orders_2025_06.csv @raw_stage/orders/;

LIST @raw_stage/orders/;

-- Check for problems without loading anything
COPY INTO orders FROM @raw_stage/orders/ VALIDATION_MODE = RETURN_ERRORS;

COPY INTO orders FROM @raw_stage/orders/
  PATTERN = '.*orders_.*[.]csv[.]gz'
  ON_ERROR = 'SKIP_FILE';
-- file | status | rows_parsed | rows_loaded ...
-- raw_stage/orders/orders_2025_06.csv.gz | LOADED | 1200 | 1200

COPY INTO orders FROM @raw_stage/orders/;   -- run again: 0 files loaded (already loaded)

CREATE OR REPLACE TABLE raw_events (src VARIANT);

INSERT INTO raw_events
SELECT PARSE_JSON('{"id": 7, "customer": {"name": "Ana", "tier": "gold"},
                    "items": [{"sku": "A1", "qty": 2}, {"sku": "B9", "qty": 1}],
                    "total": "41.50"}');

SELECT src:customer.name           AS raw_name,     -- "Ana"  (VARIANT, quoted)
       src:customer.name::STRING   AS name,         -- Ana
       src:items[0].sku::STRING    AS first_sku,    -- A1
       src:total::NUMBER(10, 2)    AS total,        -- 41.50
       src:Customer                AS wrong_case,   -- NULL (paths are case-sensitive)
       TYPEOF(src:items)           AS t             -- ARRAY
FROM raw_events;

SELECT OBJECT_CONSTRUCT('id', 1, 'ok', TRUE);       -- { "id": 1, "ok": true }

-- Oops: a bad delete
DELETE FROM orders WHERE amount > 0;
SET bad_qid = LAST_QUERY_ID();

-- Look at the data just before that statement
SELECT COUNT(*) FROM orders BEFORE(STATEMENT => $bad_qid);     -- 1200

-- Restore: clone the old version, then swap it in
CREATE TABLE orders_restored CLONE orders BEFORE(STATEMENT => $bad_qid);
ALTER TABLE orders SWAP WITH orders_restored;

DROP TABLE orders_restored;   -- now holds the damaged version
UNDROP TABLE orders_restored; -- ...and could still be brought back

-- Full dev environment in seconds, no extra storage at first
CREATE DATABASE shop_dev CLONE shop;

USE ROLE USERADMIN;
CREATE ROLE sales_read;
CREATE ROLE analyst;
GRANT ROLE sales_read TO ROLE analyst;    -- analyst inherits sales_read
GRANT ROLE analyst TO ROLE SYSADMIN;      -- keep the hierarchy connected
GRANT ROLE analyst TO USER ana;

USE ROLE SECURITYADMIN;
GRANT USAGE ON DATABASE shop TO ROLE sales_read;
GRANT USAGE ON SCHEMA shop.raw TO ROLE sales_read;
GRANT SELECT ON ALL TABLES IN SCHEMA shop.raw TO ROLE sales_read;
GRANT SELECT ON FUTURE TABLES IN SCHEMA shop.raw TO ROLE sales_read;
GRANT USAGE ON WAREHOUSE analytics_wh TO ROLE analyst;

SHOW GRANTS TO ROLE sales_read;

ALTER SESSION SET USE_CACHED_RESULT = TRUE;     -- the default

SELECT region, SUM(amount) FROM orders GROUP BY region;   -- runs on the warehouse
SELECT region, SUM(amount) FROM orders GROUP BY region;   -- identical text: result cache, ~ms

-- Not eligible: non-deterministic function
SELECT region, SUM(amount), CURRENT_TIMESTAMP() FROM orders GROUP BY region;

-- Answered from metadata, no warehouse needed
SELECT COUNT(*), MIN(id), MAX(id) FROM orders;

-- Benchmark honestly
ALTER SESSION SET USE_CACHED_RESULT = FALSE;

-- How well is the table clustered on the column we filter by?
SELECT SYSTEM$CLUSTERING_INFORMATION('events', '(TO_DATE(event_ts))');
-- {"cluster_by_keys": "LINEAR(TO_DATE(event_ts))",
--  "total_partition_count": 48211, "average_depth": 812.4, ...}   <- poor

ALTER TABLE events CLUSTER BY (TO_DATE(event_ts), tenant_id);

-- Later: depth drops as Automatic Clustering works in the background
SELECT SYSTEM$CLUSTERING_INFORMATION('events');

-- Check pruning for a typical query in the query profile:
--   TableScan: Partitions scanned 112 / Partitions total 48211
SELECT tenant_id, COUNT(*) FROM events
WHERE event_ts >= '2025-06-01' AND event_ts < '2025-06-02'
GROUP BY tenant_id;

-- Pause reclustering (and its credit use) if needed
ALTER TABLE events SUSPEND RECLUSTER;

CREATE MASKING POLICY mask_email AS (val STRING) RETURNS STRING ->
  CASE WHEN IS_ROLE_IN_SESSION('PII_READER') THEN val
       ELSE REGEXP_REPLACE(val, '.+@', '***@') END;
ALTER TABLE customers MODIFY COLUMN email SET MASKING POLICY mask_email;
-- analyst sees ***@x.io, PII_READER sees ana@x.io

CREATE ROW ACCESS POLICY by_region AS (row_region STRING) RETURNS BOOLEAN ->
  EXISTS (SELECT 1 FROM sec.region_access m
          WHERE m.role_name = CURRENT_ROLE() AND m.region = row_region);
ALTER TABLE orders ADD ROW ACCESS POLICY by_region ON (region);

-- Provider: share a secure view with a partner account
CREATE SECURE VIEW shop.public.partner_orders AS
  SELECT id, amount, created_at FROM shop.raw.orders WHERE partner_id = 42;
CREATE SHARE partner_share;
GRANT USAGE ON DATABASE shop TO SHARE partner_share;
GRANT USAGE ON SCHEMA shop.public TO SHARE partner_share;
GRANT SELECT ON VIEW shop.public.partner_orders TO SHARE partner_share;
ALTER SHARE partner_share ADD ACCOUNTS = partner_org.partner_acct;
-- Consumer: CREATE DATABASE partner_data FROM SHARE provider_org.provider_acct.partner_share;
